package alternate;public class Rational{private final long numerator,denominator;public Rational(long m,long n){long a=Math.abs(m),b=Math.abs(n);while(b!=0){long t=a%b;a=b;b=t;}long gcd=a==0?1:a;if(n<0)gcd=-gcd;numerator=m/gcd;denominator=n/gcd;}public long numerator(){return numerator;}public long denominator(){return denominator;}public Rational add(Rational b){return new Rational(numerator*b.denominator+b.numerator*denominator,denominator*b.denominator);}public Rational subtract(Rational b){return new Rational(numerator*b.denominator-b.numerator*denominator,denominator*b.denominator);}public Rational multiply(Rational b){return new Rational(numerator*b.numerator,denominator*b.denominator);}public Rational divide(Rational b){return new Rational(numerator*b.denominator,denominator*b.numerator);}public static void transform(Rational[]a){for(int i=0;i+1<a.length;i+=2)a[i]=a[i].add(a[i+1]);}public String toString(){return numerator+"/"+denominator;}}
